// Add diagnostic endpoint
[HttpGet("diagnostics")]
public IActionResult Diagnostics() {
    return Ok(new {
        Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT"),
        Memory = GC.GetTotalMemory(false),
        Threads = ThreadPool.ThreadCount
    });
